def merge_intervals(intervals):
    if not intervals:
        return []

    # Sort by start time. sorted() creates a new list, preserving the original input.
    sorted_intervals = sorted(intervals)

    merged = []
    for start, end in sorted_intervals:
        if not merged:
            merged.append([start, end])
        else:
            # Check if current interval overlaps with or touches the last interval in merged
            if start <= merged[-1][1]:
                # Merge intervals by updating the end of the last interval
                # Create a new list to avoid mutating the original intervals
                merged[-1] = [merged[-1][0], max(merged[-1][1], end)]
            else:
                merged.append([start, end])

    return merged

import heapq

def toposort(nodes, edges):
    adj = {node: set() for node in nodes}
    in_degree = {node: 0 for node in nodes}

    for u, v in edges:
        if v not in adj[u]:
            adj[u].add(v)
            in_degree[v] += 1

    heap = [node for node in nodes if in_degree[node] == 0]
    heapq.heapify(heap)

    result = []
    while heap:
        u = heapq.heappop(heap)
        result.append(u)
        for v in adj[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                heapq.heappush(heap, v)

    if len(result) < len(nodes):
        raise ValueError("Cycle detected")

    return result

def stable_batches(items, limit):
    if limit <= 0:
        raise ValueError("limit must be positive")
    batches = []
    current_batch = []
    current_weight = 0
    for name, weight in items:
        if weight <= 0 or weight > limit:
            raise ValueError("Invalid weight")
        if current_batch and current_weight + weight > limit:
            batches.append(current_batch)
            current_batch = [name]
            current_weight = weight
        else:
            current_batch.append(name)
            current_weight += weight
    if current_batch:
        batches.append(current_batch)
    return batches

import re

def parse_env(text):
    env = {}
    key_re = re.compile(r'[A-Za-z_][A-Za-z0-9_]*')

    for line in text.splitlines():
        line = line.strip()
        if not line or line.startswith('#'):
            continue

        if '=' not in line:
            raise ValueError(f"Invalid line: {line!r}")

        key, value = line.split('=', 1)
        key = key.strip()
        value = value.strip()

        if not key_re.fullmatch(key):
            raise ValueError(f"Invalid key: {key!r}")

        if len(value) >= 2 and (
            (value[0] == '"' and value[-1] == '"') or
            (value[0] == "'" and value[-1] == "'")
        ):
            value = value[1:-1]

        env[key] = value

    return env

def parse_sse(chunks):
    buffer = b''
    results = []
    current_data = []

    for chunk in chunks:
        buffer += chunk
        while b'\n' in buffer:
            line_bytes, buffer = buffer.split(b'\n', 1)
            line = line_bytes.decode('utf-8').rstrip('\r')

            if line.startswith(':'):
                continue
            if line.startswith('data:'):
                raw = line[5:]
                if raw.startswith(' '):
                    raw = raw[1:]
                current_data.append(raw)
            elif line == '':
                if current_data:
                    event_text = '\n'.join(current_data)
                    if event_text == '[DONE]':
                        return results
                    results.append(event_text)
                    current_data = []

    return results

import sys

def retry_delay(attempt, base, cap):
    if attempt < 0 or base < 0 or cap < 0:
        raise ValueError("Arguments must be nonnegative")
    if base == 0.0 or cap == 0.0:
        return 0.0

    # 2**2100 is sufficiently large that base * 2**2100 will always overflow
    # to float('inf') for any positive finite base (sys.float_info.min * 2**2097 > sys.float_info.max).
    # Thus, min(cap, inf) == cap. Capping at 2100 prevents constructing a 300M-digit integer
    # and avoids unnecessary overflow checks.
    effective_attempt = attempt if attempt < 2100 else 2100

    return min(float(cap), base * (2 ** effective_attempt))

def fifo_admit(active, queued, budget, slots):
    for q in queued:
        if q > budget:
            raise ValueError("Reservation exceeds budget")

    admitted = []
    current_slots = len(active)
    current_tokens = sum(active)

    i = 0
    for q in queued:
        if current_slots + 1 <= slots and current_tokens + q <= budget:
            admitted.append(q)
            current_slots += 1
            current_tokens += q
            i += 1
        else:
            break

    return admitted, queued[i:]
